module ShiftRegister (
  input  wire        clk,
  input  wire        reset,
  input  wire        enable,
  input  wire        data,
  output reg  [3:0]  chain
);
  reg         [3:0]  next_chain;
  wire        [3:0]  feedback;
  assign feedback = chain[0];
  always @(*) begin
    next_chain[0] = enable ? data : chain[0];
    next_chain[1] = enable ? chain[0] : chain[1];
    next_chain[2] = enable ? chain[1] : chain[2];
    next_chain[3] = enable ? chain[2] : chain[3];
  end
  always @(posedge clk) begin
    if (reset) chain <= 4'b1111;
    else       chain <= next_chain;
  end
endmodule

